    /** 图片整体背景的类型。 */
    backgroundType: string;
    /** API 背景配置。 */
    apiBackgroundConfig: apiBackgroundConfig;
    /** 自定义背景的 CSS 代码。 */
    backgroundValue: string;
    /** 水平柱状图 - 标题的字体。 */
    chartTitleFont: string;
    /** 水平柱状图 - 成员昵称和发言次数的字体。 */
